import math

def calculate_butter_amount(num_dozen):
    return num_dozen * (1/4)

def calculate_total_butter_amount(num_days):
    return calculate_butter_amount(4) * num_days

num_days = 7
total_butter_amount = calculate_total_butter_amount(num_days)

print(f"Juan will need {total_butter_amount:.2f} pounds of butter to make croissants for a week.")
