    "New York Times": 0.10,
    "Wall Street Journal": 0.08
}

# Define the prices of each newspaper
newspaper_price = {
    "New York Times": 5,
    "Wall Street Journal": 15
}

# Define the number of copies sold
newspaper_copies = {
    "New York Times": 6,
    "Wall Street Journal": 10
}

# Calculate the total commission
total_commission = sum(
    (newspaper_commission[name] * newspaper_copies[name] * math.ceil(newspaper_price[name] / 10))
    for name, price in newspaper_price.items()
    for copies in newspaper_copies.items()
)

# Print the total commission
print(total_commission)
